package kindergarten

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// Garden holds the flower beds of a kindergarten classroom: two rows of
// cups, assigned to the children in alphabetical order of their names.
type Garden struct {
	plants map[string][]string
}

var plantNames = map[byte]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

// The diagram argument starts each row with a '\n'.  This allows Go's
// raw string literals to present diagrams in source code nicely as two
// rows flush left, for example,
//
//     diagram := `
//     VVCCGG
//     VVCCGG`

// NewGarden creates a Garden from a diagram and a list of children.
// The diagram must start with a newline and contain exactly two rows of
// equal length, with an even number of cups, each coded with one of the
// known plant letters.  The children are assigned to the cups in
// alphabetical order of their names, two cups per row per child, and the
// caller's children slice is not modified.
func NewGarden(diagram string, children []string) (*Garden, error) {
	if len(diagram) == 0 || diagram[0] != '\n' {
		return nil, errors.New("diagram must start with a newline")
	}
	rows := strings.Split(diagram[1:], "\n")
	if len(rows) != 2 {
		return nil, errors.New("diagram must have exactly two rows")
	}
	if len(rows[0]) != len(rows[1]) {
		return nil, errors.New("diagram rows must be the same length")
	}
	if len(rows[0])%2 != 0 {
		return nil, errors.New("each row must contain an even number of cups")
	}
	for _, row := range rows {
		for i := 0; i < len(row); i++ {
			if _, ok := plantNames[row[i]]; !ok {
				return nil, fmt.Errorf("invalid cup code %q", row[i])
			}
		}
	}
	// Work on a copy so the caller's slice is not modified.
	names := make([]string, len(children))
	copy(names, children)
	seen := make(map[string]bool, len(names))
	for _, name := range names {
		if seen[name] {
			return nil, fmt.Errorf("duplicate child name %q", name)
		}
		seen[name] = true
	}
	sort.Strings(names)

	g := &Garden{plants: make(map[string][]string, len(names))}
	pairs := len(rows[0]) / 2
	for i, name := range names {
		if i >= pairs {
			break
		}
		g.plants[name] = []string{
			plantNames[rows[0][2*i]],
			plantNames[rows[0][2*i+1]],
			plantNames[rows[1][2*i]],
			plantNames[rows[1][2*i+1]],
		}
	}
